import sys, json, csv, io
try:
    p = json.load(sys.stdin)
    cfg = p.get("config") or {}
    text = str(cfg.get("text") or "")
    delim = (str(cfg.get("delimiter") or ",") or ",")[0]
    has_header = str(cfg.get("hasHeader", "true")).lower() != "false"
    rows = [r for r in csv.reader(io.StringIO(text), delimiter=delim) if r]
    if has_header and rows:
        header = rows[0]
        out = [dict(zip(header, r)) for r in rows[1:]]
    else:
        out = rows
    print(json.dumps({"result": {"rows": out, "count": len(out)}}))
except Exception as e:
    print(json.dumps({"result": None, "error": str(e)}))

import sys, json
try:
    p = json.load(sys.stdin)
    cfg = p.get("config") or {}
    raw = cfg.get("data")
    if isinstance(raw, str) and raw.strip():
        data = json.loads(raw)
    elif raw is not None:
        data = raw
    else:
        data = p.get("input")
    cur = data
    for part in [s for s in str(cfg.get("path") or "").split(".") if s]:
        if isinstance(cur, list) and part.lstrip("-").isdigit():
            i = int(part)
            cur = cur[i] if -len(cur) <= i < len(cur) else None
        elif isinstance(cur, dict):
            cur = cur.get(part)
        else:
            cur = None
        if cur is None:
            break
    print(json.dumps({"result": {"value": cur, "found": cur is not None}}))
except Exception as e:
    print(json.dumps({"result": None, "error": str(e)}))

import sys, json
try:
    p = json.load(sys.stdin)
    cfg = p.get("config") or {}
    raw = cfg.get("rows")
    rows = json.loads(raw) if isinstance(raw, str) else (raw or [])
    mode = str(cfg.get("mode") or "filter")
    if mode == "pick":
        keep = [s.strip() for s in str(cfg.get("fields") or "").split(",") if s.strip()]
        out = [{k: r.get(k) for k in keep} for r in rows if isinstance(r, dict)]
    else:
        f, op, val = cfg.get("field"), str(cfg.get("op") or "eq"), cfg.get("value")
        def match(r):
            v = r.get(f) if isinstance(r, dict) else None
            if op == "eq": return str(v) == str(val)
            if op == "ne": return str(v) != str(val)
            if op == "contains": return str(val) in str(v)
            try:
                if op == "gt": return float(v) > float(val)
                if op == "lt": return float(v) < float(val)
            except (TypeError, ValueError):
                return False
            return False
        out = [r for r in rows if match(r)]
    print(json.dumps({"result": {"rows": out, "count": len(out)}}))
except Exception as e:
    print(json.dumps({"result": None, "error": str(e)}))

import sys, json
import xml.etree.ElementTree as ET
def conv(el):
    node = {"tag": el.tag, "attrs": dict(el.attrib)}
    text = (el.text or "").strip()
    if text:
        node["text"] = text
    kids = [conv(c) for c in el]
    if kids:
        node["children"] = kids
    return node
try:
    p = json.load(sys.stdin)
    cfg = p.get("config") or {}
    root = ET.fromstring(str(cfg.get("xml") or ""))
    print(json.dumps({"result": conv(root)}))
except Exception as e:
    print(json.dumps({"result": None, "error": str(e)}))

import sys, json
from datetime import datetime, timezone, timedelta
try:
    p = json.load(sys.stdin)
    cfg = p.get("config") or {}
    fmt = str(cfg.get("format") or "%Y-%m-%dT%H:%M:%S%z")
    try:
        offset = float(cfg.get("utcOffsetHours") or 0)
    except (TypeError, ValueError):
        offset = 0.0
    now = datetime.now(timezone(timedelta(hours=offset)))
    print(json.dumps({"result": {"formatted": now.strftime(fmt), "iso": now.isoformat(), "epoch": int(now.timestamp())}}))
except Exception as e:
    print(json.dumps({"result": None, "error": str(e)}))

import sys, json, hashlib
try:
    p = json.load(sys.stdin)
    cfg = p.get("config") or {}
    algo = str(cfg.get("algorithm") or "sha256").lower()
    if algo not in ("md5", "sha1", "sha256", "sha512"):
        raise ValueError("unsupported algorithm: " + algo)
    text = str(cfg.get("text") or "")
    digest = hashlib.new(algo, text.encode("utf-8")).hexdigest()
    print(json.dumps({"result": {"algorithm": algo, "hex": digest}}))
except Exception as e:
    print(json.dumps({"result": None, "error": str(e)}))

import sys, json, base64
try:
    p = json.load(sys.stdin)
    cfg = p.get("config") or {}
    mode = str(cfg.get("mode") or "encode").lower()
    text = str(cfg.get("text") or "")
    if mode == "decode":
        pad = text.strip() + "=" * (-len(text.strip()) % 4)
        out = base64.b64decode(pad.encode("ascii")).decode("utf-8", "replace")
    else:
        out = base64.b64encode(text.encode("utf-8")).decode("ascii")
    print(json.dumps({"result": {"mode": mode, "output": out}}))
except Exception as e:
    print(json.dumps({"result": None, "error": str(e)}))

import sys, json, uuid
try:
    p = json.load(sys.stdin)
    cfg = p.get("config") or {}
    try:
        count = int(str(cfg.get("count") or "1"))
    except ValueError:
        count = 1
    count = max(1, min(count, 100))
    ids = [str(uuid.uuid4()) for _ in range(count)]
    print(json.dumps({"result": {"uuid": ids[0], "uuids": ids, "count": count}}))
except Exception as e:
    print(json.dumps({"result": None, "error": str(e)}))

import sys, json
try:
    p = json.load(sys.stdin)
    cfg = p.get("config") or {}
    template = str(cfg.get("template") or "")
    raw = cfg.get("values")
    values = json.loads(raw) if isinstance(raw, str) and raw.strip() else (raw or {})
    ctx = {}
    if isinstance(p.get("input"), dict):
        ctx.update(p["input"])
    if isinstance(values, dict):
        ctx.update(values)
    class Safe(dict):
        def __missing__(self, key):
            return "{" + str(key) + "}"
    rendered = template.format_map(Safe(ctx))
    print(json.dumps({"result": {"rendered": rendered}}))
except Exception as e:
    print(json.dumps({"result": None, "error": str(e)}))

import sys, json, re, collections
try:
    p = json.load(sys.stdin)
    cfg = p.get("config") or {}
    text = str(cfg.get("text") or "")
    try:
        top_n = int(str(cfg.get("topN") or "10"))
    except ValueError:
        top_n = 10
    top_n = max(1, min(top_n, 50))
    words = re.findall(r"[A-Za-z0-9']+", text.lower())
    counts = collections.Counter(words)
    top = [{"term": w, "count": c} for w, c in counts.most_common(top_n)]
    out = {
        "words": len(words),
        "unique": len(counts),
        "chars": len(text),
        "lines": len(text.splitlines()),
        "topTerms": top,
    }
    print(json.dumps({"result": out}))
except Exception as e:
    print(json.dumps({"result": None, "error": str(e)}))
